def L(sk, t, m, base, A, B, C, qq, qo, qa, mi):
    cx = {'A': A, 'B': B, 'C': C}
    s, q, o = cx[base]
    return {
        'sk': sk, 't': t, 'm': [f'{m} phút', f'{m} min'], 'base': base,
        'story': s, 'cq': q, 'co': o, 'qq': qq, 'qo': qo, 'qa': qa,
        'ctx': {k: {'s': v[0], 'q': v[1], 'o': v[2]} for k, v in cx.items() if k != base},
        'mi': {'t': mi[0], 's': mi[1], 'lv': mi[2], 'rw': mi[3]},
    }

